<template>
    <div class="ecom-element ecom-cart ecom-cart__estimate-shipping">
        <Liquid v-if="exporting" data="{%- if cart.item_count > 0 -%}" />
        <div class="ecom-cart__estimate-shipping-wrapper">
            <div
                class="ecom-cart__estimate-shipping-container"
                :data-submit-button-text="lang(data.settings.submit_label,'cart_shipping_submit_label')"
                :data-submit-disable-button-text="lang(data.settings.submit_label_calculating,'cart_shipping_submit_label_calculating')"
                v-html="liquid('estimate_shipping')"
            />
        </div>
        <Liquid v-if="exporting" data="{%- endif -%}" />
    </div>
</template>

<script>
    import { Liquid, Element, Javascript } from '@/mixins';
    export default {
        name: 'EstimateShipping',
        mixins: [Liquid, Element, Javascript],
        props: {
            data: {
                type: Object,
                default () {
                    return {};
                }
            }
        },
        computed: {
            liquids () {
                return {

                    estimate_shipping: {
                        code: `
                        <${'script'} src="//{{shop.domain}}/services/javascripts/countries.js"></${'script'}>
                        <div id="ecom-cart__estimate-shipping-calculator">
                            <div class="ecom-cart__estimate-shipping-wrapper">
                                <div class="ecom-cart__estimate-shipping-fields">
                                    <div class="ecom-cart__estimate-shipping-field">
                                        <label for="ecom-cart__estimate-shipping-address_country">${this.lang(this.data.settings.country_text, 'estimate_shipping_country_text')}</label>
                                        <select id="ecom-cart__estimate-shipping-address_country" name="address[country]" data-default="{% if shop.customer_accounts_enabled and customer %}{{ customer.default_address.country }}{% elsif settings.shipping_calculator_default_country != '' %}{{ settings.shipping_calculator_default_country }}{% endif %}">{{ country_option_tags }}</select>
                                    </div>
                                    <div class="ecom-cart__estimate-shipping-field" id="ecom-cart__estimate-shipping-address_province_container" style="display:none;">
                                        <label for="ecom-cart__estimate-shipping-address_province" id="ecom-cart__estimate-shipping-address_province_label">${this.lang(this.data.settings.province_text, 'estimate_shipping_province_text')}</label>
                                        <select id="ecom-cart__estimate-shipping-address_province" name="address[province]" data-default="{% if shop.customer_accounts_enabled and customer and customer.default_address.province != '' %}{{ customer.default_address.province }}{% endif %}"></select>
                                    </div>
                                    <div class="ecom-cart__estimate-shipping-field">
                                    <label for="ecom-cart__estimate-shipping-address_zip">${this.lang( this.data.settings.zip_postal_text, 'zip_postal_text')}</label>
                                        <input type="text" id="ecom-cart__estimate-shipping-address_zip" name="address[zip]"{% if shop.customer_accounts_enabled and customer %} value="{{ customer.default_address.zip }}"{% endif %} />
                                    </div>
                                    <div class="ecom-cart__estimate-shipping-field ecom-cart__estimate-shipping-field--button">
                                        <button type="button" class="ecom-cart__estimate-shipping-get-rates btn button" value="${this.lang( this.data.settings.submit_label, 'cart_shipping_submit_label')}" >
                                            ${this.lang( this.data.settings.submit_label, 'cart_shipping_submit_label')}
                                        </button>
                                    </div>
                                </div>
                            </div>
                            ${!this.exporting && this.data.settings?.show_success
                                ? `<p id="ecom-cart__estimate-shipping-rates-feedback" class="ecom-cart__estimate-shipping-success">Shipping rate starts at: <span class="ecom-cart__estimate-shipping-price">$30.00</span></p>`
                                : ''
                            }
                            ${!this.exporting && this.data.settings?.show_error
                                ? `<p id="ecom-cart__estimate-shipping-rates-feedback" class="ecom-cart__estimate-shipping-error">Invalid Zip/postal code</p>`
                                : ''
                            }
                            <div id="ecom-cart__estimate-shipping-wrapper-response"></div>

                            </div>


                    `,
                        preview: `
                            <div class="ecom-skeleton-item">
                                <div class="ecom-skeleton-col-12">
                                    <div class="ecom-skeleton-row">
                                        <div class="ecom-skeleton-col-3 ecom-skeleton-big"></div>
                                        <div class="ecom-skeleton-col-1 ecom-skeleton-big ecom-skeleton-empty"></div>
                                        <div class="ecom-skeleton-col-3 ecom-skeleton-big"></div>
                                        <div class="ecom-skeleton-col-1 ecom-skeleton-big ecom-skeleton-empty"></div>
                                        <div class="ecom-skeleton-col-3 ecom-skeleton-big"></div>
                                    </div>
                                    <div class="ecom-skeleton-row">
                                        <div class="ecom-skeleton-col-6 ecom-skeleton-big"></div>
                                        <div class="ecom-skeleton-col-1 ecom-skeleton-big ecom-skeleton-empty"></div>
                                        <div class="ecom-skeleton-col-4 ecom-skeleton-big"></div>
                                        <div class="ecom-skeleton-col-1 ecom-skeleton-big ecom-skeleton-empty"></div>
                                    </div>
                                </div>
                            </div>
                        `
                    }
                };
            },

            settings () {
                return [
                    {
                        group_title: this.$t('general'),
                        params: [
                            {
                                type: 'text',
                                label: this.$t('submit_button_label'),
                                name: 'submit_label',
                                placeholder: this.$t('calculate_shipping'),
                            },
                            {
                                type: 'text',
                                label: this.$t('calculating_button_label'),
                                name: 'submit_label_calculating',
                                placeholder: this.$t('calculating'),
                            },
                            {
                                type: 'text',
                                label: this.$t('country_text'),
                                name: 'country_text',
                                placeholder: this.$t('country'),
                            },
                            {
                                type: 'text',
                                label: this.$t('province_text'),
                                name: 'province_text',
                                placeholder: this.$t('province'),
                                description: this.$t('only_show_for_certain_countries'),
                            },
                            {
                                type: 'text',
                                label: this.$t('zip_postal_code_text'),
                                name: 'zip_postal_text',
                                placeholder: this.$t('zip_postal_code'),
                            },
                            {
                                type: 'toggle',
                                label: this.$t('preview_invalid_zip_postal_code'),
                                name: 'show_error',
                                options: {
                                    values:{
                                        on:{
                                            label: this.$t('yes'),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t('no'),
                                            value: false
                                        }
                                    }
                                }
                            },
                            {
                                type: 'text',
                                label: this.$t('shipping_rate_text_after_calculated'),
                                name: 'rate_price_text',
                                placeholder: this.$t('shipping_rate_starts_at_price'),
                                description: this.$t('real_shipping_rate_will_replace_price_after_calculated'),
                            },
                            {
                                type: 'toggle',
                                label: this.$t('preview_shipping_rate_after_calculated'),
                                name: 'show_success',
                                options: {
                                    values:{
                                        on:{
                                            label: this.$t('yes'),
                                            value: true
                                        },
                                        off: {
                                            label: this.$t('no'),
                                            value: false
                                        }
                                    }
                                }
                            },
                            {
                                type: 'text',
                                label: this.$t('text_when_do_not_ship_to_a_location'),
                                name: 'do_not_ship_text',
                                placeholder: this.$t('we_do_now_ship_to_this_destination'),
                            },
                            {
                                type: 'number',
                                name: 'gap',
                                label: this.$t('gap'),
                                options: {
                                    responsive: true,
                                    units: {
                                        px: {
                                            min: 0,
                                            max: 100,
                                        }
                                    }
                                },
                                css: {
                                    selector: ' .ecom-cart__estimate-shipping-fields',
                                    properties: {
                                        gap: ''
                                    }
                                }
                            },
                        ]
                    }
                ];
            },

            javascript () {
                return function () {
                    if (!this.$el || !this.settings) return;

                    var isLive = this.isLive;
                    const alertText = {
                        have: this.settings.rate_price_text || '',
                        dontHave: this.settings.do_not_ship_text || ''
                    }

                    if (typeof window.Shopify === 'undefined' || !window.Shopify) {
                        window.Shopify = window.Shopify || {};
                    }

                    if(!window.Shopify.CountryProvinceSelector) {
                        window.Shopify.CountryProvinceSelector = function(country_domid, province_domid, options) {
                            this.countryEl         = document.getElementById(country_domid);
                            this.provinceEl        = document.getElementById(province_domid);
                            this.provinceContainer = document.getElementById(options['hideElement'] || province_domid);

                            window.Shopify.addListener(this.countryEl, 'change', Shopify.bind(this.countryHandler,this));

                            this.initCountry();
                            this.initProvince();
                        };
                        window.Shopify.CountryProvinceSelector.prototype = {
                            initCountry: function() {
                                var value = this.countryEl.getAttribute('data-default');
                                window.Shopify.setSelectorByValue(this.countryEl, value);
                                this.countryHandler();
                            },

                            initProvince: function() {
                                var value = this.provinceEl.getAttribute('data-default');
                                if (value && this.provinceEl.options.length > 0) {
                                window.Shopify.setSelectorByValue(this.provinceEl, value);
                                }
                            },

                            countryHandler: function(e) {
                                var opt       = this.countryEl.options[this.countryEl.selectedIndex];
                                var raw       = opt.getAttribute('data-provinces');
                                var provinces = JSON.parse(raw);

                                this.clearOptions(this.provinceEl);
                                if (provinces && provinces.length == 0) {
                                this.provinceContainer.style.display = 'none';
                                } else {
                                for (var i = 0; i < provinces.length; i++) {
                                    var opt = document.createElement('option');
                                    opt.value = provinces[i][0];
                                    opt.innerHTML = provinces[i][1];
                                    this.provinceEl.appendChild(opt);
                                }

                                this.provinceContainer.style.display = "";
                                }
                            },

                            clearOptions: function(selector) {
                                while (selector.firstChild) {
                                selector.removeChild(selector.firstChild);
                                }
                            },

                            setOptions: function(selector, values) {
                                for (var i = 0, count = values.length; i < values.length; i++) {
                                var opt = document.createElement('option');
                                opt.value = values[i];
                                opt.innerHTML = values[i];
                                selector.appendChild(opt);
                                }
                            }
                        };
                        window.Shopify.bind = function(fn, scope) {
                            return function() {
                                return fn.apply(scope, arguments);
                            }
                        };
                        window.Shopify.addListener = function(target, eventName, callback) {
                            target.addEventListener ? target.addEventListener(eventName, callback, false) : target.attachEvent('on'+eventName, callback);
                        };
                        window.Shopify.setSelectorByValue = function(selector, value) {
                            for (var i = 0, count = selector.options.length; i < count; i++) {
                                var option = selector.options[i];
                                if (value == option.value || value == option.innerHTML) {
                                selector.selectedIndex = i;
                                return i;
                                }
                            }
                        };
                    }
                    let _appendDom = function(data){
                        let element = '';

                        if(data.rates[0]){
                          let price = new Intl.NumberFormat('en-US', { style: 'currency', currency: data.rates[0].currency }).format(data.rates[0].price);
                          let string = alertText.have.replace('{{price}}', `<span class="ecom-cart__estimate-shipping-price">${price}</span>`);
                          element = `
                              <p id="ecom-cart__estimate-shipping-rates-feedback"  class="${data.success ? 'ecom-cart__estimate-shipping-success': 'ecom-cart__estimate-shipping-error'}">
                                  ${data.success && data.rates && data.rates[0].price && data.rates[0].currency
                                      ? string
                                      : alertText.dontHave
                              }
                                  </p>`
                        }
                        else{
                          element = `<p id="ecom-cart__estimate-shipping-rates-feedback" class="ecom-cart__estimate-shipping-success">${alertText.dontHave}</p>`
                        }
                        return element;
                    }

                    if (typeof window.EComposer === 'undefined' || !window.EComposer) {
                        window.EComposer = window.EComposer || {};
                    }
                    'undefined' == typeof window.EComposer.Cart && (window.EComposer.Cart = {});

                    let $container = this.$el.querySelector('.ecom-cart__estimate-shipping-container');
                    if (!$container) return;

                    // Per-instance config — scoped to this container so multiple instances
                    // (e.g. one mobile section + one desktop section) don't interfere.
                    var _config = {
                        submitButton: $container.dataset.submitButtonText || 'Calculate shipping',
                        submitButtonDisabled: $container.dataset.submitDisableButtonText || 'Calculating...',
                        wrapperId: 'ecom-cart__estimate-shipping-wrapper-response',
                        customerIsLoggedIn: !!window.EComposer.customer,
                        moneyFormat: window.EComposer.money_format,
                    };

                    let _render = function (e) {
                        var r = $container.querySelectorAll('#' + _config.wrapperId);
                        if (r.length) {
                            r[0].innerHTML = _appendDom(e);
                        }
                    };

                    let _enableButtons = function () {
                        let btn = $container.querySelector('.ecom-cart__estimate-shipping-get-rates');
                        if (!btn) return;
                        btn.classList.remove('disabled');
                        btn.removeAttribute('disabled');
                        btn.innerHTML = _config.submitButton;
                    };

                    let _disableButtons = function () {
                        let btn = $container.querySelector('.ecom-cart__estimate-shipping-get-rates');
                        if (!btn) return;
                        btn.classList.add('disabled');
                        btn.setAttribute('disabled', 'disabled');
                        btn.innerHTML = _config.submitButtonDisabled;
                    };

                    let _getCartShippingRatesForDestination = function (e) {
                        window.fetch('/cart/prepare_shipping_rates.json', {
                            method: 'POST',
                            body: JSON.stringify({ shipping_address: e }),
                            headers: { "Content-Type": "application/json" }
                        })
                            .then(function(response){ return response.json() })
                            .then(function(response){
                                if (response == null) {
                                    _pollForCartShippingRatesForDestination(e);
                                } else {
                                    _onError(response);
                                }
                            })
                            .catch(function(error){ _onError(error); });
                    };

                    let _pollForCartShippingRatesForDestination = function (e) {
                        window.fetch('/cart/async_shipping_rates.json', { method: "GET" })
                            .then(function(response) { return response.json(); })
                            .then(function(response){
                                let res = Object.assign({}, response.shipping_rates);
                                _onCartShippingRatesUpdate(res, e);
                            })
                            .catch(function(error){ _onError(error); });
                    };

                    let _onError = function (XMLHttpRequest, code) {
                        if (code === 'error' && isLive) {
                            window.alert('This feature only work on live site');
                            _enableButtons();
                            return 1;
                        }
                        let element = $container.querySelector('#' + _config.wrapperId);
                        if (!element) return;
                        if (XMLHttpRequest.zip && XMLHttpRequest.zip[0]) {
                            element.innerHTML = `<p id="ecom-cart__estimate-shipping-rates-feedback" class="ecom-cart__estimate-shipping-error">${XMLHttpRequest.zip[0]}</p>`;
                        }
                        _enableButtons();
                        element.style.display = 'block';
                    };

                    let _onCartShippingRatesUpdate = function (e, t) {
                        _enableButtons();
                        _render({ rates: e, success: !0 });
                        let wrapper = $container.querySelector('#' + _config.wrapperId);
                        if (!wrapper) return;
                        wrapper.style.display = 'block';
                    };

                    let _formatRate = function (e) {
                        function t (e, t) {
                            return 'undefined' == typeof e ? t : e;
                        }
                        function r (e, r, n, a) {
                            if (
                                ((r = t(r, 2)),
                                    (n = t(n, ',')),
                                    (a = t(a, '.')),
                                    isNaN(e) || null == e)
                            ) { return 0; }
                            e = (e / 100).toFixed(r);
                            var i = e.split('.'),
                                o = i[0].replace(/(\d)(?=(\d\d\d)+(?!\d))/g, '$1' + n),
                                s = i[1] ? a + i[1] : '';
                            return o + s;
                        }
                        if ('function' == typeof window.EComposer.formatMoney) { return window.EComposer.formatMoney(e, _config.moneyFormat); }
                        'string' == typeof e && (e = e.replace('.', ''));
                        var n = '',
                            a = /\{\{\s*(\w+)\s*\}\}/,
                            i = _config.moneyFormat;
                        switch (i.match(a)[1]) {
                            case 'amount':
                                n = r(e, 2);
                                break;
                            case 'amount_no_decimals':
                                n = r(e, 0);
                                break;
                            case 'amount_with_comma_separator':
                                n = r(e, 2, '.', ',');
                                break;
                            case 'amount_no_decimals_with_comma_separator':
                                n = r(e, 0, '.', ',');
                        }
                        return i.replace(a, n);
                    };

                    // Generate unique IDs per container so CountryProvinceSelector (which uses
                    // document.getElementById internally) targets the correct elements when
                    // multiple EstimateShipping instances exist on the same page.
                    let _allContainers = document.querySelectorAll('.ecom-cart__estimate-shipping-container');
                    let _idx = Array.from(_allContainers).indexOf($container);
                    let _sfx = _idx > 0 ? '_' + _idx : '';

                    let _countryId           = 'ecom-cart__estimate-shipping-address_country' + _sfx;
                    let _provinceId          = 'ecom-cart__estimate-shipping-address_province' + _sfx;
                    let _provinceContainerId = 'ecom-cart__estimate-shipping-address_province_container' + _sfx;

                    let _countryEl           = $container.querySelector('[name="address[country]"]');
                    let _provinceEl          = $container.querySelector('[name="address[province]"]');
                    let _provinceContainerEl = $container.querySelector('[id*="address_province_container"]');

                    if (_countryEl)           _countryEl.id           = _countryId;
                    if (_provinceEl)          _provinceEl.id          = _provinceId;
                    if (_provinceContainerEl) _provinceContainerEl.id = _provinceContainerId;

                    try {
                        if (window.Shopify && window.Shopify.CountryProvinceSelector) {
                            new window.Shopify.CountryProvinceSelector(
                                _countryId,
                                _provinceId,
                                { hideElement: _provinceContainerId }
                            );

                            let elGetRate = $container.querySelector('.ecom-cart__estimate-shipping-get-rates');
                            if (!elGetRate) return;
                            elGetRate.addEventListener('click', function(){
                                _disableButtons();
                                let wrapper = $container.querySelector('#' + _config.wrapperId);
                                if (!wrapper) return;
                                wrapper.innerHTML = '';
                                wrapper.style.display = 'none';
                                let e = {};
                                let zip      = $container.querySelector('#ecom-cart__estimate-shipping-address_zip');
                                let country  = $container.querySelector('[name="address[country]"]');
                                let province = $container.querySelector('[name="address[province]"]');
                                e.zip      = zip      ? zip.value      : '';
                                e.country  = country  ? country.value  : '';
                                e.province = province ? province.value : '';
                                _getCartShippingRatesForDestination(e);
                            });

                            function trigger(el, eventType) {
                                if (typeof eventType === 'string' && typeof el[eventType] === 'function') {
                                    el[eventType]();
                                } else {
                                    const event = typeof eventType === 'string'
                                        ? new Event(eventType, {bubbles: true})
                                        : eventType;
                                    el.dispatchEvent(event);
                                }
                            }

                            _config.customerIsLoggedIn && trigger(elGetRate, 'click');
                            trigger(elGetRate, new PointerEvent('pointerover'));
                        }
                    }
                    catch(e) {
                        console.warn(e.message);
                    }

                    // Keep global reference for external use (last-mounted instance wins)
                    window.EComposer.Cart.ShippingCalculator = {
                        getConfig:  function ()  { return _config; },
                        formatRate: function (e) { return _formatRate(e); },
                    };
                }
            },

            requestShopifyType () {
                return {
                    shopify_type: 'cart'
                };
            },
            style () {
                return [
                    {
                        group_alias: 'box',
                        options: {
                            group_title: this.$t('general'),
                            // selector: '.ecom-cart__estimate-shipping-wrapper'
                        },
                        modify: {
                            params: [
                                {
                                    position: 0,
                                    fields: [
                                        {
                                            alias: "justify-content",
                                            options: {
                                            label: this.$t('alignment'),
                                            css: {
                                                selector: "root .ecom-cart__estimate-shipping-wrapper",
                                                properties:{
                                                    'justify-content':'',
                                                    'align-items':''
                                                }
                                            }
                                    }
                                        }
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_alias: 'text',
                        options: {
                            group_name: 'label',
                            group_title: this.$t('label'),
                            selector: ' .ecom-cart__estimate-shipping-field label'
                        },
                        modify: {
                            remove: {
                                index: 0,
                                length: 1
                            }
                        }

                    },
                    {
                        group_alias: 'input',
                        options: {
                            group_name: 'select',
                            group_title: this.$t('location_select'),
                            selector: 'root .ecom-cart__estimate-shipping-field select'
                        },
                        modify: {
                            remove: [
                                {
                                    index: 6,
                                    length: 2,
                                },
                                {
                                    index: 3,
                                    length: 1,
                                },
                            ],
                            params: [
                                {
                                    position: 0,
                                    fields: [
                                        {
                                            type: "number",
                                            name: "width",
                                            label: this.$t('width'),
                                            options: {
                                                responsive: true,
                                                reset: true,
                                                units: {
                                                    px: {
                                                        min: 0,
                                                        max: 1000
                                                    }
                                                }
                                            },
                                            css: {
                                                properties: {
                                                    "width": ""
                                                }
                                            }
                                        },
                                        {
                                            type: "number",
                                            name: "height",
                                            label: this.$t('height'),
                                            options: {
                                                responsive: true,
                                                reset: true,
                                                units: {
                                                    px: {
                                                        min: 0,
                                                        max: 100
                                                    }
                                                }
                                            },
                                            css: {
                                                properties: {
                                                    "height": ""
                                                }
                                            }
                                        },
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_alias: 'input',
                        options: {
                            group_name: 'input',
                            group_title: this.$t('input_box'),
                            selector: 'root #ecom-cart__estimate-shipping-address_zip'
                        },
                        modify: {
                            remove: [
                                {
                                    index: 3,
                                    length: 1
                                },
                                {
                                    index: 5,
                                    length: 2
                                }
                            ],
                            params: [
                                {
                                    position: 0,
                                    fields: [
                                        {
                                            type: "number",
                                            name: "width",
                                            label: this.$t('width'),
                                            options: {
                                                responsive: true,
                                                reset: true,
                                                units: {
                                                    px: {
                                                        min: 0,
                                                        max: 1000
                                                    }
                                                }
                                            },
                                            css: {
                                                properties: {
                                                    "width": ""
                                                }
                                            }
                                        },
                                        {
                                            type: "number",
                                            name: "height",
                                            label: this.$t('height'),
                                            options: {
                                                responsive: true,
                                                reset: true,
                                                units: {
                                                    px: {
                                                        min: 0,
                                                        max: 100
                                                    }
                                                }
                                            },
                                            css: {
                                                properties: {
                                                    "height": ""
                                                }
                                            }
                                        },
                                    ]
                                }
                            ]
                        }
                    },
                    {
                        group_alias: 'button',
                        options: {
                            selector: ' .ecom-cart__estimate-shipping-get-rates.button'
                        },
                        modify: {
                            params: [
                                {
                                    position: 1,
                                    fields: [
                                        {
                                            alias: 'justify-content',
                                            options: {
                                                label: this.$t('alignment'),
                                                css: {
